@Test
void resolveSuccess() {
    MSEntraJWTSSOProvider provider = new MSEntraJWTSSOProvider(userDAO, authDataAccessor, TENANT_ID, APP_ID, AUTH_USERNAME, Duration.ofMinutes(5), verifier());
    when(userDAO.findByUsername(anyString())).thenAnswer(ic -> Optional.of(user));
    when(authDataAccessor.getAuthorities(AUTH_USERNAME, null)).thenReturn(Set.of(mock(SyncopeGrantedAuthority.class)));
    when(user.getUsername()).thenReturn(AUTH_USERNAME);
    Instant now = OffsetDateTime.now(ZoneOffset.UTC).toInstant();
    Instant issued = now.minus(65, ChronoUnit.SECONDS);
    Instant notBefore = now.minus(5, ChronoUnit.SECONDS);
    Instant expiration = now.plus(1, ChronoUnit.HOURS);
    JWTClaimsSet payload = new JWTClaimsSet.Builder().issuer(TENANT_ID).audience(APP_ID).issueTime(Date.from(issued)).notBeforeTime(Date.from(notBefore)).expirationTime(Date.from(expiration)).build();
    Pair<User, Set<SyncopeGrantedAuthority>> resolved = provider.resolve(payload);
    assertEquals(AUTH_USERNAME, resolved.getKey().getUsername());
    assertEquals(1, resolved.getValue().size());
}

